// <summary>
/// PricingAttribute of table <c>SalesTable</c> field SalesId
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesTable, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(SalesTable, SalesId))]
internal class METGUPPricingAttributeSalesTableSalesID extends METGUPPricingAttributeSalesTable implements GUPIPricingAttribute
{
}

Method.Source:
/// <summary>
/// Returns value of the attribute field
/// </summary>
/// <param name = "_pricingObject">Returns value of the attribute field</param>
/// <returns></returns>
public anytype getValueOfAttribute(Common _pricingObject)
{
    return this.getTableRecord(_pricingObject).SalesId;
}

/// <summary>
/// Returns display name of the attribute field
/// </summary>
/// <returns>Returns display name of the attribute field</returns>
public str getName()
{
    return fieldPName(SalesTable, SalesId);
}

/// <summary>
/// Returns data type of the table field for attribute
/// </summary>
/// <returns>Returns data type of the table field for attribute</returns>
public AttributeDataType getDataType()
{
    return AttributeDataType::Text;
}

/// <summary>
/// Returns field number of the table field for attribute
/// </summary>
/// <returns>Returns field number of the table field for attribute</returns>
public FieldId getField()
{
    return fieldNum(SalesTable, SalesId);
}

/// <summary>
///Gets the path of the attribute tables
/// </summary>
public GUPPricingAttributeTableFieldPath getPath()
{
    return METConstants::pathNotExist;
}
